250	// unchanged (idempotent). Once frozen, name, version and the three counts
251	// can never change again.
252	func (s *Store) FreezeCircuit(name string, version int) (Circuit, error) {
253		if err := validateCircuitKey(name, version); err != nil {
254			return Circuit{}, err
255		}
256	
257		var result Circuit
258		err := s.withLock(func() (bool, error) {
259			existing := findCircuit(s.data.Circuits, name, version)
260			if existing == nil {
261				return false, notFoundf("circuit %q version %d does not exist", name, version)
262			}
263			if existing.Frozen {
264				result = circuitFromPersist(*existing)
265				return false, nil
266			}
267			existing.Frozen = true
268			result = circuitFromPersist(*existing)
269			return true, nil
270		})
271		return result, err
272	}
273	
274	// CopyCircuit creates a new draft version of a circuit name by copying a
275	// frozen source version. The target version must be a positive integer
276	// different from the source version; it need not be consecutive or greater.
277	//
278	// The copy carries over the source's description, constraint count, public
279	// and private input counts, and — when the source has one — its complete
280	// constraint definition (modulus, constraint order and wire layout). A
281	// counts-only source produces a counts-only target with no definition. The
282	// new draft is fully independent: updating, re-importing or freezing it
283	// never touches the source, and the source's compiled artifacts, trusted
284	// setup and registered jobs are never copied or bound to the target. The
285	// target must register its own setup and compile its own artifact after
286	// freezing; the source's hash cannot satisfy the target's input checks or
287	// job bindings.
288	//
289	// Copying is idempotent: if the target already exists as a draft whose
290	// description, counts and definition are semantically equal to the source,
291	// the stored target is returned unchanged and nothing is written. A frozen
292	// target or a target whose description, counts or definition has changed
293	// yields ErrConflict. An unknown source yields ErrNotFound and an unfrozen
294	// source ErrNotFrozen; the source is always checked before the target.
295	func (s *Store) CopyCircuit(name string, version, toVersion int) (Circuit, error) {
296		if err := validateCircuitKey(name, version); err != nil {
297			return Circuit{}, err
298		}
299		if err := validateCircuitKey(name, toVersion); err != nil {
300			return Circuit{}, err
301		}
302		if version == toVersion {
303			return Circuit{}, invalidf("source and target version must differ for circuit %q", name)
304		}
305	
306		var result Circuit
307		err := s.withLock(func() (bool, error) {
308			source := findCircuit(s.data.Circuits, name, version)
309			if source == nil {
310				return false, notFoundf("circuit %q version %d does not exist", name, version)
311			}
312			if !source.Frozen {
313				return false, notFrozenf("circuit %q version %d must be frozen before it can be copied as a new draft", name, version)
314			}
315			target := findCircuit(s.data.Circuits, name, toVersion)
316			if target != nil {
317				if target.Frozen {
318					return false, conflictf("circuit %q version %d already exists and is frozen", name, toVersion)
319				}
320				if !circuitCopyMatches(*source, *target) {
321					return false, conflictf("circuit %q version %d already exists with content that differs from the source", name, toVersion)
322				}
323				result = circuitFromPersist(*target)
324				return false, nil
325			}
326			record := persistCircuit{
327				Name: name, Version: toVersion,
328				Constraints: source.Constraints, PublicInputs: source.PublicInputs, PrivateInputs: source.PrivateInputs,
329				Frozen: false, Description: source.Description,
330			}
331			if source.Definition != nil {
332				def := *source.Definition
333				record.Definition = &def
334			}
335			s.data.Circuits = append(s.data.Circuits, record)
336			result = circuitFromPersist(record)
337			return true, nil
338		})
339		return result, err
340	}
341	
342	// RecordSetup records a trusted setup for one frozen circuit version. The
343	// record belongs exclusively to that name+version. Unknown versions yield
344	// ErrNotFound; non-frozen versions yield ErrNotFrozen. Re-registering a
345	// setup for the same version is idempotent and adds no duplicate record.
346	func (s *Store) RecordSetup(name string, version int) (Setup, error) {
347		if err := validateCircuitKey(name, version); err != nil {
348			return Setup{}, err
349		}
350	
351		var result Setup
352		err := s.withLock(func() (bool, error) {
353			circuit := findCircuit(s.data.Circuits, name, version)
354			if circuit == nil {
355				return false, notFoundf("circuit %q version %d does not exist", name, version)
356			}
357			if !circuit.Frozen {
358				return false, notFrozenf("circuit %q version %d must be frozen before its trusted setup is recorded", name, version)
359			}
360			if existing := findSetup(s.data.Setups, name, version); existing != nil {
361				result = setupFromPersist(*existing)
362				return false, nil
363			}
364			record := persistSetup{Name: name, Version: version}
365			s.data.Setups = append(s.data.Setups, record)
366			result = setupFromPersist(record)
367			return true, nil
368		})
369		return result, err
370	}
371	
372	// SubmitJob accepts and stores a prove job. Only kind "prove" is accepted;
373	// no proving computation runs, the accepted request alone is persisted.
374	//
375	// The job id must be non-empty and not only whitespace and must be complete,
376	// valid UTF-8: the id is the job's identity and is looked up by exact value,
377	// and encoding/json silently rewrites invalid byte sequences (a lone
378	// continuation byte, a truncated multi-byte character, an encoded surrogate
379	// half, …) to U+FFFD when the record is marshaled, so accepting them would
380	// save the job under a different id than the caller submitted (and could
381	// collide with an id that genuinely contains "�"). Such a request is refused
382	// as ErrInvalidArgument before anything is committed. Circuit name and
383	// version must be explicit and Attempt must be positive. Failure reasons are
384	// distinguishable: ErrNotFound (version unknown), ErrNotFrozen (version is
385	// still a draft) and ErrSetupMissing (no trusted setup for that version). A
386	// refused submission leaves no job behind.
387	//
388	// A non-empty CompiledHash additionally binds the job to the pinned
389	// version's compiled artifact, matched as the exact string: a version with
390	// no compiled artifact yields ErrArtifactMissing and a hash that differs
391	// from that artifact's hash yields ErrArtifactMismatch. Artifacts of other
392	// names or versions never satisfy the binding. An empty CompiledHash leaves
393	// the job unbound and keeps the register-only behavior.
394	//
395	// Resubmitting the same id with the same request — including the same
396	// optional hash — returns the stored job; the same id with different content
397	// yields ErrConflict, reported before any artifact check of the new request.
398	// A stored job stays pinned to the version submitted, regardless of circuit
399	// versions added later.
400	func (s *Store) SubmitJob(job Job) (Job, error) {
401		if strings.TrimSpace(job.ID) == "" {
402			return Job{}, invalidf("job id must be non-empty and not only whitespace")
403		}
404		if !utf8.ValidString(job.ID) {
405			return Job{}, invalidf("job id must be valid UTF-8: the submitted id contains invalid byte sequences (a lone continuation byte or a truncated multi-byte character) that would be rewritten to a replacement character when saved")
406		}
407		if strings.TrimSpace(job.Circuit) == "" {
408			return Job{}, invalidf("job %q must name a circuit", job.ID)
409		}
410		if job.Version <= 0 {
411			return Job{}, invalidf("job %q must pin a positive circuit version", job.ID)
412		}
413		if job.Attempt <= 0 {
414			return Job{}, invalidf("job %q attempt must be a positive integer", job.ID)
415		}
416		if job.Kind != "prove" {
417			return Job{}, StoreError{Kind: ErrUnsupportedKind.Kind,
418				Detail: "job " + job.ID + " has unsupported kind " + job.Kind + "; only \"prove\" jobs are accepted"}
419		}
420	
421		var result Job
422		err := s.withLock(func() (bool, error) {
423			if existing := findJob(s.data.Jobs, job.ID); existing != nil {
424				if !sameJobRequest(*existing, job) {
425					return false, conflictf("job %q already exists with a different request", job.ID)
426				}
427				result = jobFromPersist(*existing)
428				return false, nil
429			}
430			circuit := findCircuit(s.data.Circuits, job.Circuit, job.Version)
431			if circuit == nil {
432				return false, notFoundf("job %q references unknown circuit %q version %d", job.ID, job.Circuit, job.Version)
433			}
434			if !circuit.Frozen {
435				return false, notFrozenf("job %q references circuit %q version %d which is not frozen", job.ID, job.Circuit, job.Version)
436			}
437			if findSetup(s.data.Setups, job.Circuit, job.Version) == nil {
438				return false, setupMissingf("job %q references frozen circuit %q version %d which has no recorded trusted setup",
439					job.ID, job.Circuit, job.Version)
440			}
441			if job.CompiledHash != "" {
442				artifact := findArtifact(s.data.Artifacts, job.Circuit, job.Version)
443				if artifact == nil {
444					return false, artifactMissingf("job %q references circuit %q version %d which has no compiled artifact",
445						job.ID, job.Circuit, job.Version)
446				}
447				if artifact.Hash != job.CompiledHash {
448					return false, artifactMismatchf("artifact hash %q does not belong to circuit %q version %d (bound hash %q)",
449						job.CompiledHash, job.Circuit, job.Version, artifact.Hash)
450				}
451			}
452			record := persistJob{
453				ID: job.ID, Circuit: job.Circuit, Version: job.Version,
454				Kind: job.Kind, Attempt: job.Attempt, Artifact: job.Artifact,
455				CompiledHash: job.CompiledHash,
456			}
457			s.data.Jobs = append(s.data.Jobs, record)
458			result = jobFromPersist(record)
459			return true, nil
460		})
461		return result, err
462	}
463	
464	// GetCircuit returns one circuit version, sorted-field populated exactly as
465	// stored. Unknown versions yield ErrNotFound.
466	func (s *Store) GetCircuit(name string, version int) (Circuit, error) {
467		if err := validateCircuitKey(name, version); err != nil {
468			return Circuit{}, err
469		}
470		var result Circuit
471		err := s.withLockRead(func() error {
472			existing := findCircuit(s.data.Circuits, name, version)
473			if existing == nil {
474				return notFoundf("circuit %q version %d does not exist", name, version)
475			}
476			result = circuitFromPersist(*existing)
477			return nil
478		})
479		return result, err
480	}
481	
482	// ListCircuits returns all stored circuit versions ordered by circuit name
483	// (lexicographically) and then by ascending version number.
484	func (s *Store) ListCircuits() ([]Circuit, error) {
485		var result []Circuit
486		err := s.withLockRead(func() error {
487			ordered := append([]persistCircuit(nil), s.data.Circuits...)
488			sort.Slice(ordered, func(i, j int) bool {
489				if ordered[i].Name != ordered[j].Name {
490					return ordered[i].Name < ordered[j].Name
491				}
492				return ordered[i].Version < ordered[j].Version
493			})
494			result = make([]Circuit, len(ordered))
495			for i, c := range ordered {
496				result[i] = circuitFromPersist(c)
497			}
498			return nil
499		})
500		return result, err
501	}
502	
503	// GetSetup reports whether a trusted setup is registered for the named
504	// frozen version. A missing record yields ErrNotFound.
505	func (s *Store) GetSetup(name string, version int) (Setup, bool, error) {
506		if err := validateCircuitKey(name, version); err != nil {
507			return Setup{}, false, err
508		}
509		var result Setup
510		found := false
511		err := s.withLockRead(func() error {
512			existing := findSetup(s.data.Setups, name, version)
513			if existing == nil {
514				return nil
515			}
516			result = setupFromPersist(*existing)
517			found = true
518			return nil
519		})
520		return result, found, err
521	}
522	
523	// GetJob returns one stored job by id. Unknown ids yield ErrNotFound.
524	func (s *Store) GetJob(id string) (Job, error) {
525		if strings.TrimSpace(id) == "" {
526			return Job{}, invalidf("job id must be non-empty and not only whitespace")
527		}
528		var result Job
529		err := s.withLockRead(func() error {
530			existing := findJob(s.data.Jobs, id)
531			if existing == nil {
532				return notFoundf("job %q does not exist", id)
533			}
534			result = jobFromPersist(*existing)
535			return nil
536		})
537		return result, err
538	}
539	
540	// ListJobs returns all accepted jobs ordered by job id lexicographically.
541	func (s *Store) ListJobs() ([]Job, error) {
542		var result []Job
543		err := s.withLockRead(func() error {
544			ordered := append([]persistJob(nil), s.data.Jobs...)
545			sort.Slice(ordered, func(i, j int) bool { return ordered[i].ID < ordered[j].ID })
546			result = make([]Job, len(ordered))
547			for i, j := range ordered {
548				result[i] = jobFromPersist(j)
549			}
550			return nil
551		})
552		return result, err
553	}
554	
555	// --- validation helpers ---------------------------------------------------
556	
557	func validateCircuitKey(name string, version int) error {
558		if strings.TrimSpace(name) == "" {
559			return invalidf("circuit name must be non-empty and not only whitespace")
560		}
561		if version <= 0 {
562			return invalidf("circuit %q version must be a positive integer, got %d", name, version)
563		}
564		return nil
565	}
566	
567	// maxInputWires is the largest declared input count that stays representable
568	// on the running platform. Wire numbering always reserves wire 0 for the
569	// constant one, so the wires a version names are 0 plus its public and private
570	// inputs: the declared counts must satisfy 1 + public + private <= M, where M
571	// is the largest positive value the platform's int can hold. The check is done
572	// without ever adding the counts, so a layout whose sum would wrap (e.g.
573	// public=M with one private input) is refused rather than accepted through
574	// integer wraparound as a small, representable layout.
575	const maxInputWires = math.MaxInt
576	
577	// inputLayoutRepresentable reports whether the constant wire plus the public
578	// and private inputs fits inside the platform's int. Callers already guarantee
579	// both counts are non-negative.
580	func inputLayoutRepresentable(publicInputs, privateInputs int) bool {
581		return publicInputs <= maxInputWires-1 && privateInputs <= maxInputWires-1-publicInputs
582	}
583	
584	func validateCounts(constraints, publicInputs, privateInputs int) error {
585		if constraints <= 0 {
586			return invalidf("constraints must be greater than zero, got %d", constraints)
587		}
588		if publicInputs < 0 {
589			return invalidf("public input count must not be negative, got %d", publicInputs)
590		}
591		if privateInputs < 0 {
592			return invalidf("private input count must not be negative, got %d", privateInputs)
593		}
594		if !inputLayoutRepresentable(publicInputs, privateInputs) {
595			return invalidf("input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
596				publicInputs, privateInputs, maxInputWires)
597		}
598		return nil
599	}
600	
601	// --- lookup / mapping helpers --------------------------------------------
602	
603	func findCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
604		for i := range cs {
605			if cs[i].Name == name && cs[i].Version == version {
606				return &cs[i]
607			}
608		}
609		return nil
610	}
611	
612	func findSetup(ps []persistSetup, name string, version int) *persistSetup {
613		for i := range ps {
614			if ps[i].Name == name && ps[i].Version == version {
615				return &ps[i]
616			}
617		}
618		return nil
619	}
620	
621	func findJob(js []persistJob, id string) *persistJob {
622		for i := range js {
623			if js[i].ID == id {
624				return &js[i]
625			}
626		}
627		return nil
628	}
629	
630	func sameJobRequest(stored persistJob, request Job) bool {
631		return stored.Circuit == request.Circuit &&
632			stored.Version == request.Version &&
633			stored.Kind == request.Kind &&
634			stored.Attempt == request.Attempt &&
635			stored.CompiledHash == request.CompiledHash
636	}
637	
638	func circuitFromPersist(c persistCircuit) Circuit {
639		return Circuit{
640			Name: c.Name, Version: c.Version,
641			Constraints: c.Constraints, PublicInputs: c.PublicInputs, PrivateInputs: c.PrivateInputs,
642			Frozen: c.Frozen, Description: c.Description,
643		}
644	}
645	
646	// circuitCopyMatches reports whether target is the same draft content that a
647	// copy of source would create: same description, same three counts and a
648	// semantically equal constraint definition. Definition equality follows the
649	// existing normalization semantics (terms merged per wire, coefficients
650	// reduced modulo p, zeros dropped, wires sorted ascending); a missing
651	// definition differs from a present one.
652	func circuitCopyMatches(source, target persistCircuit) bool {
653		if source.Description != target.Description {
654			return false
655		}
656		if source.Constraints != target.Constraints ||
657			source.PublicInputs != target.PublicInputs ||
658			source.PrivateInputs != target.PrivateInputs {
659			return false
660		}
661		return definitionsEqual(source.Definition, target.Definition, source.PublicInputs, source.PrivateInputs)
662	}
663	
664	// definitionsEqual compares two stored definitions for semantic equality.
665	// Both nil is equal; one nil and the other not is different. When both are
666	// present they are parsed through the existing normalization pipeline and
667	// compared by modulus, constraint count and each side's wire/coefficient
668	// pairs. The public/private layout is the source's; the caller has already
669	// confirmed the counts match.
670	func definitionsEqual(d1, d2 *persistDefinition, public, private int) bool {
671		if d1 == nil && d2 == nil {
672			return true
673		}
674		if d1 == nil || d2 == nil {
675			return false
676		}
677		p1, err := definitionFromPersist(*d1, public, private)
678		if err != nil {
679			return false
680		}
681		p2, err := definitionFromPersist(*d2, public, private)
682		if err != nil {
683			return false
684		}
685		if p1.modulus != p2.modulus || len(p1.constraints) != len(p2.constraints) {
686			return false
687		}
688		for i := range p1.constraints {
689			if !canonicalTermsEqual(p1.constraints[i].a, p2.constraints[i].a) ||
690				!canonicalTermsEqual(p1.constraints[i].b, p2.constraints[i].b) ||
691				!canonicalTermsEqual(p1.constraints[i].c, p2.constraints[i].c) {
692				return false
693			}
694		}
695		return true
696	}
697	
698	// canonicalTermsEqual reports whether two normalized term slices are
699	// identical wire-by-wire and coefficient-by-coefficient.
700	func canonicalTermsEqual(t1, t2 []parsedTerm) bool {
701		if len(t1) != len(t2) {
702			return false
703		}
704		for i := range t1 {
705			if t1[i].wire != t2[i].wire || t1[i].value != t2[i].value {
706				return false
707			}
708		}
709		return true
710	}
711	
712	func setupFromPersist(p persistSetup) Setup {
713		return Setup{Name: p.Name, Version: p.Version}
714	}
715	
716	func jobFromPersist(j persistJob) Job {
717		return Job{
718			ID: j.ID, Circuit: j.Circuit, Version: j.Version,
719			Kind: j.Kind, Attempt: j.Attempt, Artifact: j.Artifact,
720			CompiledHash: j.CompiledHash,
721		}
722	}
