13	
14	// These tests pin the input-layout representability rule. Wire 0 always names
15	// the constant-one wire, so a version declares 1 + public + private wires; the
16	// sum must fit in the running platform's int (M = math.MaxInt). The rule is
17	// enforced with overflow-safe comparisons on every write path — create, whole
18	// replacement and partial update — and again when committed data is read.
19	
20	const emptySidesDef = `{"modulus":"7","constraints":[{"a":[],"b":[],"c":[]}]}`
21	
22	// TestCreateInputLayoutBoundaries drives create across the representable
23	// boundary in both directions.
24	func TestCreateInputLayoutBoundaries(t *testing.T) {
25		M := math.MaxInt
26		cases := []struct {
27			name    string
28			public  int
29			private int
30			wantErr bool
31		}{
32			{"zero zero keeps the constant wire", 0, 0, false},
33			{"max-1 public, zero private", M - 1, 0, false},
34			{"zero public, max-1 private", 0, M - 1, false},
35			{"max public, one private wraps", M, 1, true},
36			{"one public, max private wraps", 1, M, true},
37			{"max public, zero private already overflows the constant slot", M, 0, true},
38			{"zero public, max private plus constant overflows", 0, M, true},
39			{"max both", M, M, true},
40			{"splitting the one spare slot exactly", 1, M - 2, false}, // 1+1+M-2 = M
41			{"one past the split spare slot", 1, M - 1, true},         // 1+1+M-1 = M+1
42		}
43		for _, tc := range cases {
44			t.Run(tc.name, func(t *testing.T) {
45				s := openTestStore(t)
46				_, err := s.CreateCircuit(Circuit{Name: "c", Version: 1, Constraints: 1,
47					PublicInputs: tc.public, PrivateInputs: tc.private})
48				if tc.wantErr {
49					if !errors.Is(err, ErrInvalidArgument) {
50						t.Fatalf("want ErrInvalidArgument, got %v", err)
51					}
