447	// Both entry points run the same binding and verdict rules: the same
448	// frozen version, hash and legal inputs yield identical conclusions, and
449	// the same gating errors in the same order.
450	func TestCheckInputEntryPointsEquivalent(t *testing.T) {
451		s := openTestStore(t)
452		seedDraftWithDef(t, s, "c", 1, 1, 1, validDef)
453		s.FreezeCircuit("c", 1)
454		a, _ := s.CompileCircuit("c", 1)
455	
456		docs := map[string]string{
457			"good":       `{"public":["2"],"private":["3"]}`,
458			"negative":   `{"public":["-5"],"private":["-4"]}`,
459			"huge":       `{"public":["7000000000000000000000002"],"private":["3"]}`,
460			"unsatisfy":  `{"public":["2"],"private":["4"]}`,
461			"badwitness": `{"public":["2"]}`,
462		}
463		for name, doc := range docs {
464			t.Run(name, func(t *testing.T) {
465				path := writeTempJSON(t, doc)
466				fileRes, fileErr := s.CheckInputFile("c", 1, a.Hash, path)
467				if name == "badwitness" {
468					if !errors.Is(fileErr, ErrInvalidInput) {
469						t.Fatalf("file entry: want input format error, got %v", fileErr)
470					}
471					// The JSON witness's strict grammar rejects the document
472					// before the shared layout rules run; the in-API witness
473					// instead supplies the arrays directly.
474					if _, err := s.CheckInput("c", 1, a.Hash, Witness{Public: []string{"2", "x"}, Private: []string{"3"}}); !errors.Is(err, ErrInvalidInput) {
475						t.Fatalf("in-API entry: want input format error, got %v", err)
476					}
477					return
478				}
479				if fileErr != nil {
480					t.Fatalf("file entry: %v", fileErr)
481				}
482				w, werr := parseWitness([]byte(doc), 1, 1)
483				if werr != nil {
484					t.Fatal(werr)
485				}
486				directRes, err := s.CheckInput("c", 1, a.Hash, w)
487				if err != nil {
488					t.Fatalf("direct entry: %v", err)
489				}
490				if directRes != fileRes {
491					t.Fatalf("verdicts differ: direct=%+v file=%+v", directRes, fileRes)
492				}
493			})
494		}
495	
496		// Empty/nil slices are accepted for declared-zero groups through the
497		// direct entry; the JSON entry needs explicit arrays.
498		zero := `{"modulus":"7","constraints":[
499			{"a":[{"wire":0,"coeff":"1"}],"b":[{"wire":0,"coeff":"1"}],"c":[{"wire":0,"coeff":"1"}]}]}`
500		if _, err := s.CreateCircuit(Circuit{Name: "z", Version: 1, Constraints: 1, Description: "z"}); err != nil {
501			t.Fatal(err)
502		}
503		if _, err := s.ImportConstraints("z", 1, writeTempJSON(t, zero)); err != nil {
504			t.Fatal(err)
505		}
506		s.FreezeCircuit("z", 1)
507		az, _ := s.CompileCircuit("z", 1)
508		for _, w := range []Witness{
509			{Public: []string{}, Private: []string{}},
510			{Public: nil, Private: nil},
511		} {
512			res, err := s.CheckInput("z", 1, az.Hash, w)
513			if err != nil || !res.Satisfied || res.Hash != az.Hash {
514				t.Fatalf("nil/empty direct witness %+v: %+v %v", w, res, err)
515			}
516		}
517		path := writeTempJSON(t, `{"public":[],"private":[]}`)
518		res, err := s.CheckInputFile("z", 1, az.Hash, path)
519		if err != nil || !res.Satisfied {
520			t.Fatalf("explicit empty JSON arrays: %+v %v", res, err)
521		}
522		for _, doc := range []string{`{"private":[]}`, `{"public":[]}`, `{"public":null,"private":[]}`} {
523			if _, err := s.CheckInputFile("z", 1, az.Hash, writeTempJSON(t, doc)); !errors.Is(err, ErrInvalidInput) {
