22		ErrSetupMissing = StoreError{Kind: "trusted setup missing"}
23		// ErrUnsupportedKind means a job kind other than prove was submitted.
24		ErrUnsupportedKind = StoreError{Kind: "unsupported job kind"}
25		// ErrDefinitionMissing means a frozen version has registered counts but no
26		// imported constraint definition, so it cannot be compiled.
27		ErrDefinitionMissing = StoreError{Kind: "constraint definition missing"}
28		// ErrArtifactMissing means the version has no compiled artifact.
29		ErrArtifactMissing = StoreError{Kind: "compiled artifact missing"}
30		// ErrArtifactMismatch means the supplied hash does not belong to the
31		// target version's compiled artifact.
32		ErrArtifactMismatch = StoreError{Kind: "artifact mismatch"}
33		// ErrInvalidInput means a witness document is malformed or does not match
34		// the version's declared input layout.
