14	// These tests pin the CLI contract for the input-layout representability rule:
15	// an unrepresentable create/update is a rule failure (exit 1) with a clear
16	// message and no success record; the representable boundary (M-1 public, 0
17	// private) still creates and queries; and a committed record beyond the bound
18	// makes every data command fail at open with exit 3.
19	
20	func TestCLICreateInputLayoutOverflow(t *testing.T) {
21		dir := filepath.Join(t.TempDir(), "bench")
22		type res struct {
23			code int
24			out  string
25			err  string
26		}
27		call := func(args ...string) res {
28			c, o, e := runCapture(t, args...)
29			return res{c, o, e}
30		}
31	
32		// public = M, private = 1 must be refused, not accepted through wraparound.
33		r := call("circuit-create", "--dir", dir, "--name", "c", "--version", "1",
34			"--constraints", "1",
35			"--public-inputs", strconv.Itoa(math.MaxInt), "--private-inputs", "1")
36		if r.code != 1 {
37			t.Fatalf("overflow create: want exit 1, got %d (out=%q err=%q)", r.code, r.out, r.err)
38		}
39		if r.out != "" {
40			t.Fatalf("overflow create printed a success record: %q", r.out)
41		}
42		if !strings.Contains(r.err, "invalid argument") || !strings.Contains(r.err, "not representable") {
43			t.Fatalf("overflow create error must explain the layout limit: %q", r.err)
44		}
45	
46		// public = M on its own already leaves no room for the constant wire.
47		if r := call("circuit-create", "--dir", dir, "--name", "c", "--version", "1",
48			"--constraints", "1",
49			"--public-inputs", strconv.Itoa(math.MaxInt)); r.code != 1 ||
50			!strings.Contains(r.err, "not representable") {
51			t.Fatalf("public=M only: code=%d err=%q", r.code, r.err)
52		}
53	
54		// The refused create left no record behind.
55		if r := call("circuit-list", "--dir", dir); r.code != 0 || strings.Contains(r.out, "name=c") {
56			t.Fatalf("refused create left a record: code=%d out=%q", r.code, r.out)
57		}
58	
59		// The exact representable boundary still creates and queries normally.
60		if r := call("circuit-create", "--dir", dir, "--name", "edge", "--version", "1",
61			"--constraints", "1",
62			"--public-inputs", strconv.Itoa(math.MaxInt-1), "--private-inputs", "0"); r.code != 0 {
63			t.Fatalf("boundary create: code=%d err=%q", r.code, r.err)
64		}
65		if r := call("circuit-get", "--dir", dir, "--name", "edge", "--version", "1"); r.code != 0 ||
66			!strings.Contains(r.out, "public_inputs="+strconv.Itoa(math.MaxInt-1)) ||
67			!strings.Contains(r.out, "private_inputs=0") {
68			t.Fatalf("boundary query: code=%d out=%q err=%q", r.code, r.out, r.err)
69		}
70	
71		// Zero public and zero private inputs still keep the constant wire: a
72		// 0/0 draft creates cleanly.
73		if r := call("circuit-create", "--dir", dir, "--name", "zero", "--version", "1",
74			"--constraints", "1",
75			"--public-inputs", "0", "--private-inputs", "0"); r.code != 0 {
76			t.Fatalf("zero/zero create: code=%d err=%q", r.code, r.err)
77		}
78	}
