80	func TestCLIUpdateInputLayoutOverflow(t *testing.T) {
81		dir := filepath.Join(t.TempDir(), "bench")
82		type res struct {
83			code int
84			out  string
85			err  string
86		}
87		call := func(args ...string) res {
88			c, o, e := runCapture(t, args...)
89			return res{c, o, e}
90		}
91	
92		if r := call("circuit-create", "--dir", dir, "--name", "c", "--version", "1",
93			"--constraints", "2", "--public-inputs", "1", "--private-inputs", "3",
94			"--description", "初稿"); r.code != 0 {
95			t.Fatalf("create: %+v", r)
96		}
97	
98		// Change only the public count; the retained 3 private inputs push M past
99		// the bound. A description supplied in the same change must be refused too.
100		if r := call("circuit-update", "--dir", dir, "--name", "c", "--version", "1",
101			"--public-inputs", strconv.Itoa(math.MaxInt), "--description", "x"); r.code != 1 ||
102			!strings.Contains(r.err, "not representable") {
103			t.Fatalf("public=M with retained private=3: code=%d err=%q", r.code, r.err)
104		}
105		// Change only the private count; the retained 1 public input pushes.
106		if r := call("circuit-update", "--dir", dir, "--name", "c", "--version", "1",
107			"--private-inputs", strconv.Itoa(math.MaxInt)); r.code != 1 ||
108			!strings.Contains(r.err, "not representable") {
109			t.Fatalf("private=M with retained public=1: code=%d err=%q", r.code, r.err)
110		}
111	
112		// Counts and description all stay as they were.
113		r := call("circuit-get", "--dir", dir, "--name", "c", "--version", "1")
114		if r.code != 0 ||
115			!strings.Contains(r.out, "constraints=2") || !strings.Contains(r.out, "public_inputs=1") ||
116			!strings.Contains(r.out, "private_inputs=3") || !strings.Contains(r.out, `description="初稿"`) {
117			t.Fatalf("rejected update leaked: %+v", r)
118		}
119	
120		// Reaching the exact boundary through partial edits stays possible.
121		if r := call("circuit-update", "--dir", dir, "--name", "c", "--version", "1",
122			"--private-inputs", "0"); r.code != 0 {
123			t.Fatalf("zero private: %+v", r)
124		}
125		if r := call("circuit-update", "--dir", dir, "--name", "c", "--version", "1",
126			"--public-inputs", strconv.Itoa(math.MaxInt-1)); r.code != 0 ||
127			!strings.Contains(r.out, "public_inputs="+strconv.Itoa(math.MaxInt-1)) {
128			t.Fatalf("public=M-1 boundary: %+v", r)
129		}
130	}
131	
132	// readNumberedEnv decodes data.json preserving every integer as an exact
133	// json.Number, so a tampered MaxInt-sized value is not degraded through
134	// float64 before the strict int decoder sees it.
135	func readNumberedEnv(t *testing.T, path string) map[string]any {
136		t.Helper()
137		raw, err := os.ReadFile(path)
138		if err != nil {
139			t.Fatal(err)
140		}
141		dec := json.NewDecoder(bytes.NewReader(raw))
142		dec.UseNumber()
143		var env map[string]any
144		if err := dec.Decode(&env); err != nil {
145			t.Fatal(err)
146		}
147		return env
148	}
149	
150	func writeNumberedEnv(t *testing.T, path string, env map[string]any) []byte {
151		t.Helper()
152		raw, err := json.MarshalIndent(env, "", "  ")
153		if err != nil {
154			t.Fatal(err)
155		}
156		raw = append(raw, '\n')
157		if err := os.WriteFile(path, raw, 0o644); err != nil {
158			t.Fatal(err)
159		}
160		return raw
161	}
