163	func TestCLICommittedOverflowLayoutExitThree(t *testing.T) {
164		dir := filepath.Join(t.TempDir(), "bench")
165		type res struct {
166			code int
167			out  string
168			err  string
169		}
170		call := func(args ...string) res {
171			c, o, e := runCapture(t, args...)
172			return res{c, o, e}
173		}
174	
175		// Commit the representable boundary, then tamper one private input into
176		// the file: 1 + (M-1) + 1 = M+1.
177		if r := call("circuit-create", "--dir", dir, "--name", "edge", "--version", "1",
178			"--constraints", "1",
179			"--public-inputs", strconv.Itoa(math.MaxInt-1), "--private-inputs", "0"); r.code != 0 {
180			t.Fatalf("create boundary: %+v", r)
181		}
182		path := filepath.Join(dir, "data.json")
183		env := readNumberedEnv(t, path)
184		rec := env["circuits"].([]any)[0].(map[string]any)
185		rec["private_inputs"] = json.Number("1")
186		bad := writeNumberedEnv(t, path, env)
187	
188		for _, args := range [][]string{
189			{"circuit-list", "--dir", dir},
190			{"circuit-get", "--dir", dir, "--name", "edge", "--version", "1"},
191		} {
192			r := call(args...)
193			if r.code != 3 {
194				t.Fatalf("%s: want exit 3, got %d (out=%q err=%q)", args[0], r.code, r.out, r.err)
195			}
196			if r.out != "" {
197				t.Fatalf("%s printed partial results despite corruption: %q", args[0], r.out)
198			}
199			if !strings.Contains(r.err, "read failed") || !strings.Contains(r.err, "data corrupt") ||
200				!strings.Contains(r.err, "not representable") {
201				t.Fatalf("%s: unexpected error %q", args[0], r.err)
202			}
203		}
204	
205		left, err := os.ReadFile(path)
206		if err != nil {
207			t.Fatal(err)
208		}
209		if string(left) != string(bad) {
210			t.Fatal("refused read modified data.json")
211		}
212	}
