	badDef := writeFile(t, work, "bad.json2", `{"modulus":"9","constraints":[]}`)
	if r := call("constraint-import", "--dir", dir, "--name", "mul", "--version", "1",
		"--file", badDef); r.code != 1 || !strings.Contains(r.err, "prime") {
		t.Fatalf("composite modulus: %+v", r)
	}
