	if r := call("circuit-freeze", "--dir", dir, "--name", "mul", "--version", "1"); r.code != 0 {
		t.Fatalf("freeze: %+v", r)
	}
	r1 := call("circuit-compile", "--dir", dir, "--name", "mul", "--version", "1")
	if r1.code != 0 || !strings.Contains(r1.out, "hash=") {
		t.Fatalf("compile: %+v", r1)
	}
